// Package source turns a declared source into content harnaas can install.
//
// The manifest layer parses a source and resolves nothing: `github:acme/assets@v1`
// is checked for shape, and whether that repository exists, whether the ref
// points anywhere and what is at the path are all questions it deliberately does
// not ask. This package answers them, and it is the only place in harnaas that
// reaches the network or reads content out of a repository.
//
// Two things shape it. Every source kind answers the same question — given a
// parsed source and a path within it, produce the files and the provenance
// needed to record what landed — so the kinds sit behind one contract and a
// [Registry] dispatches to them by name. And a resolved source is worthless
// unless it can be re-identified later: `lint` has to answer "did somebody edit
// this?" and "has upstream moved?" independently, months after the install, from
// nothing but what was recorded. That is why a [Resolved] carries a digest per
// file and one over the source as a whole, and why the only way to obtain one is
// a constructor that computes both.
package source

import (
	"context"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Kind resolves the sources of one kind for one install run.
//
// It is created per run rather than registered as a value, because resolution is
// not stateless: a repository archive is fetched at most once per repository and
// commit per run, and the memory of what has already been fetched belongs to the
// run that did it. A kind shared across runs would either leak that memory
// between them or need a global cache to hold it.
type Kind interface {
	// Resolve produces the content and provenance for one asset's source.
	//
	// It is handed one asset rather than one `sources` entry because the unit
	// being resolved is the subtree an asset names, and because every diagnostic
	// raised here has to name the asset the author would go and edit.
	Resolve(ctx context.Context, req Request) (*Resolved, error)
}

// NewKind constructs a kind's resolver for one install run. It is what a kind
// registers, for the reason [Kind] gives.
type NewKind func(RunOptions) Kind

// RunOptions are the caller's choices for one resolution run.
//
// They are handed to every kind at construction rather than to [Kind.Resolve]
// per asset, because they describe the run and not the request: two assets of
// one install cannot disagree about whether the cache may be read.
type RunOptions struct {
	// Cache is where fetched content is reused from and kept for later runs. A
	// nil cache is the caller-facing bypass, and is deliberately the zero value:
	// a caller that has not said which cache to use has not said one may be
	// read, which is the answer that cannot surprise anybody.
	Cache *ArchiveCache

	// Offline is a run that must make no network request at all — not for
	// content, and not to ask a remote what a name points at. Every source is
	// satisfied from Cache and from what is already in the project, and one that
	// is in neither fails naming itself.
	//
	// Failing is the whole point. The alternatives an offline run could take —
	// skipping the asset, treating it as unchanged, or serving whatever content
	// this machine last happened to hold under that name — each turn a run that
	// could not do what it was asked into one that reports success, and the
	// third installs a different commit than the manifest declared.
	//
	// It is the zero value for the same reason a nil Cache is: a caller that has
	// not asked for an offline run has not said the network is unavailable, and
	// an offline run with no Cache can satisfy no remote source at all.
	Offline bool
}

// Request is one asset's resolution: the asset being resolved and the `sources`
// entry it references.
//
// The asset travels whole rather than as the two or three fields a kind reads,
// because the fields a diagnostic needs are not the fields resolution needs — a
// message names the asset's id and its position in the manifest, and narrowing
// the request would make every kind's errors worse to keep the struct smaller.
type Request struct {
	// Asset is the manifest entry being resolved, already interpreted: its
	// reference, type and id are settled before anything is fetched.
	Asset manifest.Asset

	// Source is the parsed `sources` entry the asset references. It is the zero
	// value for the project-local form, which references no entry.
	Source manifest.Source
}

// Kind reports which source kind must resolve this request.
//
// The project-local form declares no `sources` entry and is local by definition
// of the manifest grammar, not by anything a caller decides. Answering it here,
// once, is what keeps the install flow above and the kinds below from each
// restating that rule — and from restating it differently.
func (r Request) Kind() manifest.SourceKind {
	if r.Asset.Ref.Local() {
		return manifest.SourceKindLocal
	}
	return r.Source.Kind
}

package source

import (
	"errors"
	"maps"
	"slices"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Provenance records where a resolved source came from, in the terms the
// lockfile stores and `lint` later re-checks.
//
// The requested ref is kept alongside the commit it resolved to, and the two are
// never collapsed. A lockfile holding only the commit could say whether the
// installed files still match it, but not whether the tag or branch the manifest
// asked for now points somewhere else — which is the whole of update detection.
type Provenance struct {
	// Kind is the source kind that produced the content.
	Kind manifest.SourceKind

	// Source is the normalized source, spelled the way the lockfile records it,
	// so a recorded installation names its origin without the reader consulting
	// the manifest that was current when it ran.
	Source string

	// RequestedRef is the ref the manifest asked for, exactly as written. It is
	// empty for a kind that has no refs.
	RequestedRef string

	// ResolvedCommit is the immutable commit the request resolved to, and the
	// commit the content was taken from. It is empty for a kind whose content
	// has no commit.
	ResolvedCommit string

	// Mutable reports whether the requested ref can point somewhere else
	// tomorrow — a branch can, a tag or a commit identifier cannot.
	//
	// It is about the ref and not about the content: a local source declares no
	// ref and so is never mutable, even though the file it names is edited
	// freely. Whether the bytes changed is a question the digests answer.
	Mutable bool
}

// File is one file of a resolved source.
type File struct {
	// Path is the file's location relative to the source's own root, cleaned
	// and slash-separated on every platform, so a lockfile written on Windows
	// and one written on Linux record the same install.
	Path string

	// Content is the file's bytes, exactly as they arrived. Resolution never
	// rewrites content — not even a skill's frontmatter, whose `name` it checks
	// and refuses to correct.
	Content []byte

	// Digest is the digest of Content, computed once here so no later phase has
	// to re-read the file to say which of several files changed.
	Digest Digest
}

// Resolved is one asset's source, fetched and verified: every file it consists
// of, the digests that re-identify them, and where they came from.
//
// The content is held in memory rather than left in a directory a caller must
// clean up. Harness assets are documents and resolution bounds their total size
// before anything is read, so the bytes cost little; what it buys is that
// rendering and digesting are pure functions of a value, with no temporary
// directory whose lifetime has to outlive the phase that created it.
type Resolved struct {
	// Provenance is where the content came from.
	Provenance Provenance

	// Files is every resolved file, sorted by path. Sorted rather than mapped
	// because this order is what the digest is computed over, what the lockfile
	// records and what a report lists — three places that must not disagree.
	Files []File

	// Digest covers the whole source: every path and every file's digest. It is
	// what says "upstream moved", independently of the installed digest that
	// says "somebody edited this".
	Digest Digest
}

// errEmptySource reports a resolved source with no files in it.
//
// It is a distinct error because the condition it prevents is specific: a
// retrieval that failed halfway must never be handed on as a source that
// legitimately resolved to nothing, which would converge to deleting every file
// the asset had installed. Making the constructor refuse it is what turns that
// from a rule each kind follows into one none of them can break.
var errEmptySource = errors.New("resolved source contains no files")

// errEmptyPath reports a file with no path, which would leave the whole-source
// digest unable to distinguish it from a file that was not there at all.
var errEmptyPath = errors.New("resolved source names a file with an empty path")

// NewResolved builds a resolved source from its provenance and its files, given
// as the path-to-content mapping extraction produces.
//
// It is the only way to obtain a [Resolved], so every value of that type has
// sorted files, a digest per file and a whole-source digest computed the same
// way — a kind cannot produce one whose digest disagrees with its content, and
// no later phase has to check that it did.
func NewResolved(provenance Provenance, content map[string][]byte) (*Resolved, error) {
	if len(content) == 0 {
		return nil, errEmptySource
	}

	files := make([]File, 0, len(content))
	for _, path := range slices.Sorted(maps.Keys(content)) {
		if path == "" {
			return nil, errEmptyPath
		}
		files = append(files, File{
			Path:    path,
			Content: content[path],
			Digest:  DigestContent(content[path]),
		})
	}

	return &Resolved{Provenance: provenance, Files: files, Digest: digestFiles(files)}, nil
}

package github

import (
	"context"
	"errors"
	"net/http"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/source"
)

// Kind resolves every `github` source of one install run.
//
// It is built per run rather than registered as a value because it holds the
// run's archives: several assets naming different subtrees of one repository at
// one commit share a single retrieval, and that memory is only correct for as
// long as the run that made it.
type Kind struct {
	run      gitRunner
	archives *archives

	// credential is the run's token, read from the environment chain once at
	// construction rather than per retrieval. A run is one identity: reading the
	// chain per asset would let a variable changed mid-run split one install
	// into two identities, and would make "which token was this?" a question
	// with a different answer for each diagnostic.
	credential source.Credential

	// offline is the run's answer to whether the network may be reached, held
	// here as well as in the archive memo because a resolution makes two kinds
	// of request and this is where the first one is decided.
	offline bool
}

// New returns the kind for one install run.
//
// It is what the source registry registers, and the fetcher it builds is the
// only way harnaas makes an HTTP request — so every transport rule applies here
// by there being no second route to a request.
func New(opts source.RunOptions) source.Kind {
	return newKind(runGit, source.NewFetcher().Fetch, ambientCredential(), opts)
}

// newKind is [New] with the git invocation, the retrieval and the credential as
// parameters, so a whole resolution is exercisable with neither a network, a
// repository nor a token in the environment the suite runs under. The run's own
// choices arrive as the options they arrive as everywhere else, so a field added
// to them reaches this kind without another parameter.
func newKind(run gitRunner, fetch archiveFetcher, credential source.Credential, opts source.RunOptions) *Kind {
	return &Kind{
		run:        run,
		archives:   newArchives(fetch, opts),
		credential: credential,
		offline:    opts.Offline,
	}
}

// Resolve produces one asset's content and provenance.
//
// The three steps are deliberately separate: the declared ref becomes a commit
// before anything is fetched, the commit's archive is retrieved at most once per
// run, and the subtree the asset names is taken out of it. Every failure is
// attributed to the asset, and none of them returns a resolved source — an empty
// one would converge to deleting every file the asset had installed, which is
// why [source.NewResolved] refuses one and why nothing here builds a [source.Resolved]
// by any other route.
func (k *Kind) Resolve(ctx context.Context, req source.Request) (*source.Resolved, error) {
	resolution, err := k.resolution(ctx, req)
	if err != nil {
		return nil, err
	}

	archive, err := k.archives.get(ctx, req.Source.Repository, resolution.Commit, k.credential)
	if err != nil {
		return nil, k.retrievalFailure(req, resolution.Commit, err)
	}

	content, err := source.ExtractSubtree(archive, req.Asset.Ref.Path, source.ArchiveSubject{
		AssetID: req.Asset.ID,
		Source:  req.Source.String(),
		Commit:  resolution.Commit,
	})
	if err != nil {
		return nil, err
	}

	resolved, err := source.NewResolved(source.Provenance{
		Kind:   manifest.SourceKindGitHub,
		Source: req.Source.String(),
		// The ref is recorded beside the commit and never collapsed into it:
		// "the installed files still match the commit" and "the tag now points
		// somewhere else" are the two questions lint asks separately.
		RequestedRef:   req.Source.Ref,
		ResolvedCommit: resolution.Commit,
		Mutable:        resolution.Mutable,
	}, content)
	if err != nil {
		return nil, k.retrievalFailure(req, resolution.Commit, err)
	}

	return resolved, nil
}

// resolution turns the declared ref into the commit it names, by the one route
// the run has: the remote where the network is available, and the ref itself
// where it is not.
//
// The branch is here rather than inside the lookup so that an offline run makes
// no request at all — a lookup that decided to refuse would still be a lookup,
// and "no ref lookup is attempted" is the property offline mode is asked for.
func (k *Kind) resolution(ctx context.Context, req source.Request) (RefResolution, error) {
	if k.offline {
		return resolveRefOffline(req)
	}

	return resolveRef(ctx, k.run, remoteURL(req.Source.Repository), req)
}

// retrievalFailure attributes a retrieval that produced no usable archive to the
// asset that asked for it.
//
// A refusal is separated from every other failure here rather than in the memo,
// because the memo holds what the transport answered and nothing about which
// asset read it — and because the credential is the run's, not the archive's. A
// second asset meeting the remembered refusal therefore gets a message naming
// itself and the same token.
func (k *Kind) retrievalFailure(req source.Request, commit string, err error) error {
	// An offline miss is checked first because it is not a failure of the
	// retrieval: nothing was asked, so there is no host, status or cause to
	// report, and the only fix is a run with the network available.
	if errors.Is(err, errNotCached) {
		return &OfflineArchiveError{
			AssetID:    req.Asset.ID,
			Repository: req.Source.Repository,
			Commit:     commit,
		}
	}

	var status *source.StatusError
	if errors.As(err, &status) && deniesAccess(status.StatusCode) {
		return &AuthorizationError{
			AssetID:     req.Asset.ID,
			Repository:  req.Source.Repository,
			Commit:      commit,
			TokenOrigin: k.credential.Origin,
			Err:         err,
		}
	}

	return &ArchiveRetrievalError{
		AssetID:    req.Asset.ID,
		Repository: req.Source.Repository,
		Commit:     commit,
		Err:        err,
	}
}

// deniesAccess reports whether a status is the forge declining to serve this
// request rather than a failure of any other kind.
//
// Not found is one of them, which is not the obvious reading. GitHub answers 404
// rather than 403 for a repository the request may not see, so that a stranger
// cannot learn a private repository exists by asking — and by the time an
// archive is fetched, ref resolution has already proved that the repository
// exists and holds this commit. It proved it over Git, with the credentials the
// user's Git configuration supplies, which are not the token this request
// carries. A "not found" here is therefore the forge declining to admit to
// harnaas's *HTTP* identity what it just admitted to its Git one.
func deniesAccess(status int) bool {
	switch status {
	case http.StatusUnauthorized, http.StatusForbidden, http.StatusNotFound:
		return true
	default:
		return false
	}
}

package manifest

import (
	"fmt"
	"path"
	"slices"
	"strings"
)

// AssetType is what an asset is, in the vocabulary the harnesses and this
// project share: a skill, a rule, an instruction, a command or a persona.
type AssetType string

const (
	// AssetTypeSkill is an asset the harness loads on its own initiative when
	// its description matches the task at hand.
	AssetTypeSkill AssetType = "skill"

	// AssetTypeRule is always-on guidance installed as its own file.
	AssetTypeRule AssetType = "rule"

	// AssetTypeInstruction is always-on guidance concatenated into a managed
	// block in the project's committed memory file.
	AssetTypeInstruction AssetType = "instruction"

	// AssetTypeCommand is an asset the user invokes deliberately.
	AssetTypeCommand AssetType = "command"

	// AssetTypePersona is a delegated worker with its own model and tool budget.
	AssetTypePersona AssetType = "persona"
)

// assetTypeDirectories maps the directory that contains an asset to the type it
// names.
//
// The convention is not invented here: `skills/`, `commands/` and `agents/` are
// already how asset repositories are laid out, because that is how the
// harnesses themselves read them. `agents/` naming a persona is the one place
// harnaas reads a word it does not write — the directory name is the
// ecosystem's, and renaming it in the manifest would mean no existing
// repository could be referenced without an object per asset.
var assetTypeDirectories = map[string]AssetType{
	"skills":       AssetTypeSkill,
	"rules":        AssetTypeRule,
	"instructions": AssetTypeInstruction,
	"commands":     AssetTypeCommand,
	"agents":       AssetTypePersona,
}

// AssetTypes returns every type harnaas recognizes, in the order a diagnostic
// lists them.
//
// The order is the one the manifest's own vocabulary is written in rather than
// alphabetical, and it is fixed so two runs produce the same sentence.
func AssetTypes() []AssetType {
	return []AssetType{
		AssetTypeSkill,
		AssetTypeRule,
		AssetTypeInstruction,
		AssetTypeCommand,
		AssetTypePersona,
	}
}

// AssetRef is an asset entry's source string, parsed into where its content
// comes from and the path to it.
//
// Parsing settles the grammar and containment, and nothing else. It does not
// look the source key up, read the path or infer anything from it, because a
// string that is not one of the two accepted forms has no meaningful key and no
// meaningful path to check further.
type AssetRef struct {
	// SourceKey is the `sources` key the path is relative to. It is empty for
	// the project-local form, which is unambiguous because `sources` rejects an
	// empty key.
	SourceKey string

	// Path is the path to the asset, cleaned and slash-separated: within the
	// source for the keyed form, and relative to the project root — still
	// beginning `.harnaas/` — for the local form.
	Path string
}

// Local reports whether the reference is the project-local form.
func (r AssetRef) Local() bool {
	return r.SourceKey == ""
}

// assetSourceForms states both accepted forms, which is most of the fix for
// every string that is neither.
var assetSourceForms = fmt.Sprintf(
	"An asset source is either %q, naming a key declared in %q, or a project-local path such as %q.",
	"acme:skills/review", "sources", LocalRoot+"/rules/house-style.md",
)

// ParseAssetRef parses one asset entry's source string.
//
// The two accepted forms are distinguished by their prefix rather than by
// trying one and falling back to the other, so a string in neither form is
// reported as what it is instead of as a failed parse of a form its author
// never used.
func ParseAssetRef(index int, source string) (AssetRef, *Violation) {
	switch {
	case source == "":
		return AssetRef{}, assetSourceViolation(index,
			assetSubject(index)+" declares no source",
			fmt.Sprintf("Give the entry a source in %s. %s", FileName, assetSourceForms),
		)

	case isAbsolutePath(source):
		// Named separately from the general "neither form" case because an
		// absolute path is a specific misunderstanding — that harnaas installs
		// from anywhere on the machine — and the fix is to move the content
		// into the repository, not to add a prefix to the same path.
		return AssetRef{}, assetSourceViolation(index,
			fmt.Sprintf("%s names the absolute path %q, and every asset source is relative", assetSubject(index), source),
			fmt.Sprintf(
				"Move the content under %s/ in this repository and reference it from there, or declare its repository in %q. %s",
				LocalRoot, "sources", assetSourceForms,
			),
		)

	case strings.ContainsRune(source, '\\'):
		// A backslash is an ordinary filename character on Linux and a
		// separator on Windows, so a manifest containing one would name two
		// different files depending on who ran install. Rejecting it here, in
		// the grammar, is what keeps the same committed file mean the same
		// thing on every machine that reads it.
		return AssetRef{}, assetSourceViolation(index,
			fmt.Sprintf("%s has the source %q, which separates its path with a backslash", assetSubject(index), source),
			fmt.Sprintf("Write the path in %s with %q separators, as in %q.", FileName, "/", "acme:skills/review"),
		)

	case strings.HasPrefix(source, LocalRoot+"/"):
		return parseLocalRef(index, source)
	}

	key, rest, keyed := strings.Cut(source, ":")
	if !keyed || !validSourceKey(key) || rest == "" || strings.HasPrefix(rest, "/") {
		return AssetRef{}, notAnAssetForm(index, source)
	}

	cleaned := path.Clean(rest)
	if cleaned == "." || cleaned == ".." || strings.HasPrefix(cleaned, "../") {
		return AssetRef{}, assetSourceViolation(index,
			fmt.Sprintf("%s has the path %q, which leaves the root of the source %q", assetSubject(index), rest, key),
			fmt.Sprintf("Write the path in %s as one relative to the root of %q, without leading %q segments.", FileName, key, ".."),
		)
	}

	return AssetRef{SourceKey: key, Path: cleaned}, nil
}

// parseLocalRef checks that a project-local path stays under `.harnaas`.
//
// The check is textual and happens before anything is opened, because the
// content of a path that escapes must never be read — not even to report that
// it exists.
func parseLocalRef(index int, source string) (AssetRef, *Violation) {
	cleaned, contained := containedUnderLocalRoot(source)
	if !contained || cleaned == LocalRoot {
		return AssetRef{}, assetSourceViolation(index,
			fmt.Sprintf("%s has the local path %q, which does not stay inside %s", assetSubject(index), source, LocalRoot),
			fmt.Sprintf(
				"Move the content under %s/ and write the path without %q segments, as in %q.",
				LocalRoot, "..", LocalRoot+"/rules/house-style.md",
			),
		)
	}

	return AssetRef{Path: cleaned}, nil
}

// notAnAssetForm reports a source string in neither accepted form.
func notAnAssetForm(index int, source string) *Violation {
	return assetSourceViolation(index,
		fmt.Sprintf("%s has the source %q, which is neither of the two accepted forms", assetSubject(index), source),
		fmt.Sprintf("Rewrite the source in %s. %s", FileName, assetSourceForms),
	)
}

// isAbsolutePath reports whether a source string names a location on the
// machine rather than inside the project or a source.
//
// Both spellings are recognized on every platform: a manifest is committed and
// read on all of them, so a Windows path must be refused when the run happens
// to be on Linux and the other way round.
func isAbsolutePath(source string) bool {
	if strings.HasPrefix(source, "/") || strings.HasPrefix(source, `\\`) {
		return true
	}

	if len(source) < 3 || source[1] != ':' {
		return false
	}
	letter := source[0] | 0x20
	return letter >= 'a' && letter <= 'z' && (source[2] == '/' || source[2] == '\\')
}

// CheckSourceKey reports an asset referencing a key the `sources` block does
// not declare.
//
// It is separate from [ParseAssetRef] because the grammar is a property of the
// string and this is a property of the document: the same string is correct in
// one manifest and wrong in another, and only the second failure can name the
// keys that would have worked.
func CheckSourceKey(index int, ref AssetRef, sources map[string]Source) *Violation {
	if ref.Local() {
		return nil
	}
	if _, found := sources[ref.SourceKey]; found {
		return nil
	}

	known := make([]string, 0, len(sources))
	for key := range sources {
		known = append(known, quoted(key))
	}
	slices.Sort(known)

	fix := fmt.Sprintf("Declare %q in the %q block of %s, or correct the key on this entry.", ref.SourceKey, "sources", FileName)
	if len(known) > 0 {
		fix = fmt.Sprintf(
			"Use a key the %q block of %s declares (%s), or declare %q there.",
			"sources", FileName, strings.Join(known, ", "), ref.SourceKey,
		)
	}

	return assetSourceViolation(index,
		fmt.Sprintf("%s references the source key %q, which %q does not declare", assetSubject(index), ref.SourceKey, "sources"),
		fix,
	)
}

// InferType infers an asset's type from the directory containing it.
//
// It is separate from [InferID] because the object form suppresses inference
// one field at a time: an entry declaring `type` for a source laid out
// unconventionally still wants its id inferred from the leaf, and would
// otherwise be refused for a directory name nobody is relying on.
func InferType(index int, ref AssetRef) (AssetType, *Violation) {
	directory := path.Base(path.Dir(ref.Path))

	assetType, named := assetTypeDirectories[directory]
	if !named {
		return "", assetSourceViolation(index,
			fmt.Sprintf(
				"%s has the path %q, whose containing directory names none of the asset types",
				assetSubject(index), ref.Path,
			),
			fmt.Sprintf(
				"Either reference a path under one of %s, or write the entry in %s as an object declaring %q.",
				directoryList(), FileName, "type",
			),
		)
	}

	return assetType, nil
}

// InferID infers an asset's id from its path's leaf, with any file extension
// removed so `tone.md` and `tone` name the same asset.
func InferID(index int, ref AssetRef) (string, *Violation) {
	leaf := path.Base(ref.Path)

	// A leading dot is the extension by path.Ext's reckoning, so stripping
	// unconditionally would turn `.gitignore` into an empty id. Only a
	// non-empty remainder is an id.
	if stripped := strings.TrimSuffix(leaf, path.Ext(leaf)); stripped != "" {
		leaf = stripped
	}

	if leaf == "" || leaf == "." || leaf == ".." {
		return "", assetSourceViolation(index,
			fmt.Sprintf("%s has the path %q, whose last segment is not a name an asset can be identified by", assetSubject(index), ref.Path),
			fmt.Sprintf("Reference the asset's own file or directory, or write the entry in %s as an object declaring %q.", FileName, "id"),
		)
	}

	return leaf, nil
}

// directoryList renders the type-naming directories for a diagnostic, in the
// same fixed order [AssetTypes] uses.
func directoryList() string {
	byType := make(map[AssetType]string, len(assetTypeDirectories))
	for directory, assetType := range assetTypeDirectories {
		byType[assetType] = directory
	}

	names := make([]string, 0, len(byType))
	for _, assetType := range AssetTypes() {
		names = append(names, quoted(byType[assetType]+"/"))
	}
	return strings.Join(names, ", ")
}

