	if errors.Is(err, errArchiveTooLarge) {
		return &ArchiveTooLargeError{Subject: e.subject, Limit: e.limits.archive}
	}
	return &ArchiveFormatError{Subject: e.subject, Reason: "harnaas could not read it to the end", Err: err}
